def run_sync(coro: Coroutine[Any, Any, _T]) -> _T:
    """在同步代码里执行协程。"""
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return asyncio.run_coroutine_threadsafe(coro, _get_background_loop()).result()
    coro.close()
    raise RuntimeError(
        "run_sync 不能在事件循环中调用，异步环境请直接 await StpUtil 的异步方法"
    )
